for(const control of document.querySelectorAll('[data-slide]')){const input=control.querySelector('input');let sliding=false;const reset=()=>{control.classList.remove('dragging');control.style.setProperty('--progress','0');input.value='0';input.setAttribute('aria-valuetext','Slide right to confirm clock '+(control.dataset.slide==='IN'?'in':'out'))};input.addEventListener('pointerdown',e=>{if(e.clientX-input.getBoundingClientRect().left>70)e.preventDefault()});input.addEventListener('input',()=>{control.classList.add('dragging');control.style.setProperty('--progress',input.value/100);input.setAttribute('aria-valuetext',input.value+' percent')});input.addEventListener('change',async()=>{if(sliding||busy){reset();return}const confirmed=Number(input.value)>=95;reset();if(!confirmed)return;sliding=true;try{if(kind!==control.dataset.slide)pendingRequest=null;kind=control.dataset.slide;await clock()}finally{sliding=false;reset()}});input.addEventListener('pointercancel',reset);input.addEventListener('blur',()=>{if(!sliding)reset()})}
